"""Data for tools/build_nf.py: the new-feature epics, their cards, umbrellas, DECs and index text.

Design docs live in docs/build-plan/new-features/<GROUP>.md; cards cite them by section and
never restate them. Card order per epic: contract → storage → engines → live 17–20 → ui-spec →
ui-build → e2e → visual (Tope's order, 22 Oct).
"""
from __future__ import annotations

API_T = "apps/api/tests"


def pt(path: str) -> tuple[str, str]:
    """Named pytest command for an allow-listed API test file."""
    return (f"cd apps/api && uv run pytest -q {path.removeprefix('apps/api/')}", "all pass")


def contract(types: str, router: str, web: str, models: list[str], endpoints: list[str],
             extra_acs: list[str] | None = None, deps: list[str] | None = None, sfx: str = "01") -> dict:
    return {
        "sfx": sfx, "kind": "contract", "type": "build", "owner": "backend-safe", "budget": "S",
        "score": (1, 0, 1, 1, 0, 0), "deps": ["SEC-GATE-SCOPE"] + (deps or []),
        "title": "API contract: types, router, error envelope, tenancy, TS mirror",
        "allow": [types, types.rsplit("/", 1)[0] + "/__init__.py", router, "apps/api/app/main.py", "apps/api/app/security/idor_registry.py", "apps/api/app/safety_registry.py", web,
                  "{T}/test_nf_{py}_contract.py"],
        "goal": "Fix the request/response contract of this epic before any engine exists, so engine, live and UI cards build against one shape.",
        "acs": [
            f"Pydantic models in `{types}` carry exactly the fields listed in the epic doc §6, or in `00_BASELINE.md` B5 for the shared scan types, for: {', '.join(models)} (a test compares each model's field set to that list).",
            "Routes exist: " + "; ".join(f"`{e}`" for e in endpoints) + ". Each returns the B5 error envelope on 403, 404 and 422.",
            "Workspace B calling any route with workspace A's ids gets 404, and every route is listed in `app/security/idor_registry.py` (registry test).",
            "Every new POST/PUT/PATCH/DELETE route has an explicit `SafetySpec` in `app/safety_registry.py` that matches its real effect: no Odoo write means `odoo_mutation=False`; `bypass_writes_paused=True` only on routes that read Odoo and write nothing but Ingenium scan rows (a route that creates a plan draft follows `POST:/api/inbox/plans`). `tests/test_safety_route_registry.py` and this card's test pass in one run with `-p randomly` on.",
            f"`{web}` mirrors the field names (a test compares `app.openapi()` component keys with a TS key fixture); `pnpm typecheck` reports no error in this card's allow-list files (errors that already exist elsewhere, such as `b0_dist.test.ts`, are listed in the Tester packet, not fixed here).",
            "Handlers call one injected engine function each; with a fake engine every route returns the documented shape; this card makes no Odoo call.",
        ] + (extra_acs or []),
        "table": [
            ("workspace B sends workspace A's id", "404 with the B5 envelope"),
            ("body misses a required field", "422 `VALIDATION` envelope with the field name"),
            ("fake engine returns the documented shape", "200; response model validates"),
        ],
        "tests": [pt("{T}/test_nf_{py}_contract.py"), ("cd apps/web && pnpm typecheck", "no error in this card's allow-list files; baseline errors elsewhere listed, not fixed")],
        "context": ["apps/api/app/routers/suite_insights.py (router pattern)", "apps/api/app/security/idor_registry.py"],
    }


def storage(tables: list[str], deps: list[str], sfx: str = "02") -> dict:
    tl = ", ".join(f"`{t}`" for t in tables)
    return {
        "sfx": sfx, "kind": "storage", "type": "build", "owner": "backend-safe", "budget": "S",
        "score": (1, 1, 2, 1, 1, 0), "deps": deps,
        "title": f"App DB tables {', '.join(tables)} (Alembic, additive)",
        "allow": ["apps/api/alembic/versions/nf_{py}_tables.py", "apps/api/app/db_models.py", "{T}/test_nf_{py}_storage.py"],
        "goal": f"Create the epic's App DB tables ({tl}) exactly as the epic doc §6 and B5 describe, additively and reversibly.",
        "acs": [
            f"Tables {tl} exist after `alembic upgrade head`, each with `workspace_id`, `connection_id` (where the doc lists it) and `created_at`, plus the columns in the epic doc §6.",
            "`alembic downgrade -1` drops only these tables; upgrade → downgrade → upgrade round-trips on the test App DB.",
            "No existing table's columns, indexes or constraints change (metadata comparison test).",
            "`alembic heads` shows exactly one head after the change, and the Alembic drift test stays green.",
        ],
        "table": [
            ("fresh test App DB, upgrade head", "new tables present; drift test green"),
            ("downgrade -1", "only the new tables are gone"),
            ("an existing table's metadata before vs after", "identical"),
        ],
        "tests": [pt("{T}/test_nf_{py}_storage.py"), ("cd apps/api && uv run alembic heads", "one head")],
        "elite": "Additive only: new tables with workspace_id/connection_id/created_at (B5), FK to odoo_connections ON DELETE CASCADE where connection-scoped, index on (connection_id, created_at), JSON columns for report payloads, no change to any existing table. Revision chains after the current single head; downgrade drops only these tables. Retention follows DEC-052 (job, not schema).",
        "oracle": "The Oracle writes test_nf_{py}_storage.py first: round-trip upgrade/downgrade/upgrade on the test App DB; metadata snapshot of every pre-existing table is unchanged; single alembic head; tables and columns match the card list. Worker may not edit it.",
        "context": ["apps/api/app/db_models.py (model pattern)", "B0-ALEMBIC card (Alembic-only rule)"],
    }


def eng(sfx: str, title: str, allow: list[str], goal: str, acs: list[str], table: list[tuple[str, str]],
        score: tuple[int, ...] = (1, 1, 0, 1, 1, 0), budget: str = "M", deps: list[str] | None = None,
        tests: list[tuple[str, str]] | None = None, **kw) -> dict:
    card = {"sfx": sfx, "kind": kw.pop("kind", "engine"), "type": kw.pop("type", "build"),
            "owner": kw.pop("owner", "backend-safe"), "budget": budget, "score": score, "deps": deps,
            "title": title, "allow": allow, "goal": goal, "acs": acs, "table": table}
    card["tests"] = tests or [pt(a) for a in allow if a.endswith(".py") and ("/tests/" in a or a.startswith("{T}/"))]
    card.update(kw)
    return card


LIVE_COMMON = [
    "Every DB the test created is gone at the end (teardown asserts no `ingenium_nf_{slug}_*` name in the DB list).",
    "`docs/build-plan/verify/{id}.md` records each [Inferred] claim of the epic doc for this feature with a per-version verdict (17, 18, 19, 20).",
    "RPC calls per run stay inside the SCAN budget (B4), and the p95 on the size class S seed is recorded in PROGRESS against the epic's target.",
]


def expand(epic: dict) -> list[dict]:
    """Turn an epic's custom cards plus the standard ladder into full card dicts."""
    code, slug = epic["code"], epic["slug"]
    py = slug.replace("-", "_")
    sub = lambda s: s.replace("{T}", API_T).replace("{py}", py).replace("{slug}", slug)  # noqa: E731
    cards: list[dict] = []
    prev = None
    for spec in epic["custom"]:
        c = dict(spec)
        c["id"] = f"{code}-{c.pop('sfx')}"
        deps = c.get("deps")
        if deps is None:
            deps = [prev] if prev else []
        c["deps"] = [d[1:] if d.startswith("=") else (f"{code}-{d[1:]}" if d.startswith("@") else d) for d in deps]
        c["allow"] = [sub(a) for a in c["allow"]]
        c["tests"] = [(sub(a.replace("{T}", "tests")), b) for a, b in c["tests"]]
        for k in ("elite", "oracle", "goal"):
            if k in c:
                c[k] = sub(c[k])
        c["acs"] = [sub(a) for a in c["acs"]]
        cards.append(c)
        prev = c["id"]
    custom_ids = [c["id"] for c in cards]
    referenced = {d for c in cards for d in c["deps"]}
    leaves = [i for i in custom_ids if i not in referenced] or custom_ids[-1:]
    first = custom_ids[0]
    lid = lambda i: f"NF-EPIC-{code};NF-{i}"  # noqa: E731
    live_id, spec_id, ui_id, e2e_id, vis_id = (f"{code}-{s}" for s in ("LIVE", "SPEC", "UI", "E2E", "VIS"))
    cmds = ", ".join(f'"{c}"' for c in epic["cmds"])
    comp = f"apps/web/src/components/{slug}/"
    ladder = [
        {"id": live_id, "kind": "live", "type": "prove-live", "owner": "backend-safe", "budget": "M",
         "score": (1, 1, 0, 1, 1, 0), "deps": leaves + ["L2-HARNESS"] + epic.get("live_deps", []),
         "title": f"Live proof on Odoo 17–20 (disposable `ingenium_nf_{py}_*` DBs)",
         "allow": [f"{API_T}/odoo_live/test_nf_{py}_live.py", f"{API_T}/odoo_live/fixtures/nf_{py}.py",
                   f"docs/build-plan/verify/{live_id}.md"],
         "goal": f"Prove the {epic['name']} engine against real Odoo 17, 18, 19 and 20 with seeded Example data, and settle every [Inferred] claim in the epic doc.",
         "acs": epic["live_acs"] + [a.replace("{slug}", py).replace("{id}", live_id) for a in LIVE_COMMON],
         "table": [("Odoo 17 seed", "same result shape as 18–20; version differences only via compat"),
                   ("Odoo 20 stack not built (O20-01 not done)", "record 'not run: Odoo 20 stack' and STOP-AND-ASK"),
                   ("an [Inferred] claim is false on a version", "verify note says false; no workaround in this card")],
         "tests": [(f"cd apps/api && ODOO_LIVE=1 uv run pytest -q -m odoo_live tests/odoo_live/test_nf_{py}_live.py", "pass on 17, 18, 19 (and 20 when built)")],
         "context": ["docs/build-plan/06_TEST_STRATEGY.md (live layer)", "L2-HARNESS card"]},
        {"id": spec_id, "kind": "spec", "type": "ui-spec", "owner": "UI", "budget": "S",
         "score": (1, 1, 0, 1, 1, 0), "deps": [first, "UI-REF-STUDY", "F1-STATES"],
         "title": f"Screen spec: {epic['screen']}",
         "allow": [f"docs/design/specs/{slug}.md"],
         "goal": f"Write the per-screen spec for {epic['screen']} so the build card has one source for layout, states, copy, motion and keyboard.",
         "acs": [f"`docs/design/specs/{slug}.md` is ≤ 120 lines with the job of the screen, the one primary action ({epic['primary']}), and area {epic['area']} with 3–5 adopted reference patterns and what is deliberately different.",
                 "Every B1 state (empty, loading, partial, error, permission denied for the Ingenium role and for the Odoo user, Odoo unreachable, huge data) has designed copy that says what will happen.",
                 f"Keyboard map includes the ⌘K commands {cmds}; responsive plan for 390/768/1024/1440/1920; dark parity; motion 100–250 ms with the reduced-motion fallback.",
                 "Only existing components (`components/ui/`, F1-STATES) are named; any new one names its two uses."] + epic.get("spec_acs", []),
         "table": [("a state from B1 has no copy", "spec not done"),
                   ("a new component with one use", "replace with existing components"),
                   ("a raw colour value in the spec", "replace with a token name")],
         "tests": [(f"wc -l docs/design/specs/{slug}.md", "≤ 120"),
                   (f"rg -n '#[0-9a-fA-F]{{3,8}}\\b' docs/design/specs/{slug}.md", "no matches")],
         "context": ["`.cursor/skills/ingenium-ui-excellence/SKILL.md` (load in full first; the X-ray floor is the minimum)", "docs/build-plan/07_UI_EXCELLENCE_PROTOCOL.md §4–§6", "docs/build-plan/UI_REFERENCE_MAP.md", "docs/build-plan/REFERENCE_NOTES.md"]},
        {"id": ui_id, "kind": "ui", "type": "ui-build", "owner": "UI", "budget": "M",
         "score": (1, 1, 1, 1, 1, 0), "deps": [spec_id, live_id, "F1-TOKENS", "F1-STATES"] + epic.get("ui_deps", []),
         "title": f"Build {epic['screen']}",
         "allow": epic["pages"] + [comp, epic["web"]] + (["apps/web/src/lib/nav.ts"] if epic.get("nav") else []),
         "goal": f"Build {epic['screen']} to its spec on the existing tokens and components, wired to the contract's TS client.",
         "acs": [f"{', '.join('`' + p + '`' for p in epic['pages'])} render every B1 state from the spec in a state-preview test.",
                 f"⌘K registers {cmds} through `useCommand`.",
                 "Changed files contain no raw hex or `rgb(`; light-ish backgrounds carry dark ink (`contrast.test.ts` green).",
                 "Owner-visible copy passes the jargon guard (F1-JARGON); Odoo technical names appear only inside `TechName`."] + epic["ui_acs"],
         "table": [("API returns `partial`", "results plus the partial `Callout`; never shown as complete"),
                   ("API returns 503 `ODOO_UNREACHABLE`", "last results stamped with their time; write buttons off"),
                   ("API returns 403 `ROLE_DENIED`", "role message; no run button")],
         "tests": [(f"cd apps/web && pnpm vitest run src/components/{slug}", "all pass"),
                   ("cd apps/web && pnpm typecheck; pnpm lint", "no error in this card's allow-list files; baseline errors elsewhere listed, not fixed")],
         "context": ["`.cursor/skills/ingenium-ui-excellence/SKILL.md` (load in full first; the X-ray floor is the minimum)", f"docs/design/specs/{slug}.md", "apps/web/src/components/ui/ (existing components)"]},
        {"id": e2e_id, "kind": "e2e", "type": "test", "owner": "UI", "budget": "S",
         "score": (1, 0, 0, 1, 1, 0), "deps": [ui_id],
         "title": f"End-to-end and accessibility: {epic['screen']}",
         "allow": [f"apps/web/e2e/nf-{slug}.spec.ts", f"apps/web/e2e/fixtures/nf-{slug}.json"],
         "goal": f"Prove the {epic['screen']} flow end to end in a browser with mocked API responses, keyboard-only and with axe.",
         "acs": [f"`apps/web/e2e/nf-{slug}.spec.ts` walks: {epic['flow']}.",
                 "Keyboard only (Tab, Enter, Esc, ⌘K) completes the primary action; focus is always visible (WCAG 2.4.11).",
                 "Mocked 503 `ODOO_UNREACHABLE` shows the last results with their time stamp and turns off write buttons; mocked 403 `ROLE_DENIED` shows the role message and no run button.",
                 "axe reports zero serious or critical issues on every state at 1440 and 390 widths; targets ≥ 24 px (WCAG 2.5.8)."],
         "table": [("primary flow with fixtures", "completes; final state matches the fixture"),
                   ("any axe serious/critical", "fail"),
                   ("partial fixture", "partial banner visible, counts labelled")],
         "tests": [(f"cd apps/web && INGENIUM_DIST_DIR=.next-build-{e2e_id.lower()} pnpm playwright test e2e/nf-{slug}.spec.ts", "all pass on port 3100")],
         "context": ["`.cursor/skills/ingenium-ui-excellence/SKILL.md` (load in full first; the X-ray floor is the minimum)", "docs/build-plan/06_TEST_STRATEGY.md (E2E layer)", f"docs/design/specs/{slug}.md"]},
        {"id": vis_id, "kind": "vis", "type": "test", "owner": "UI", "budget": "XS",
         "score": (0, 0, 0, 1, 1, 0), "deps": [e2e_id],
         "title": f"Visual check and contact sheet: {epic['screen']}",
         "allow": [f"apps/web/e2e/nf-{slug}.visual.spec.ts", f"apps/web/e2e/nf-{slug}.visual.spec.ts-snapshots/", f"docs/vision-verify/{slug}/"],
         "goal": f"Lock the look of {epic['screen']} with a visual snapshot and give Tope one contact sheet for GATE-B.",
         "acs": [f"`docs/vision-verify/{slug}/` holds one contact sheet: baseline, after and final × light and dark × 1440×900 and 390×844.",
                 f"`apps/web/e2e/nf-{slug}.visual.spec.ts` passes three runs in a row with no diff.",
                 "`apps/web/src/lib/a11y/contrast.test.ts` is green, and no state shows light ink on a light-ish background.",
                 "A trace of the primary flow at 4× CPU shows INP < 200 ms and CLS < 0.05; motion is < 300 ms and off under reduced motion.",
                 "The Worker packet has the side-by-side statement against the area's two references."],
         "table": [("snapshot differs on run 2 or 3", "flaky; fix the cause, not the threshold"),
                   ("contrast failure in dark mode only", "fail"),
                   ("contact sheet missing 390 dark", "fail")],
         "tests": [(f"cd apps/web && INGENIUM_DIST_DIR=.next-build-{vis_id.lower()} pnpm playwright test e2e/nf-{slug}.visual.spec.ts --repeat-each=3", "no diff"),
                   ("cd apps/web && pnpm vitest run src/lib/a11y/contrast.test.ts", "pass")],
         "context": ["`.cursor/skills/ingenium-ui-excellence/SKILL.md` (load in full first; the X-ray floor is the minimum)", "docs/build-plan/07_UI_EXCELLENCE_PROTOCOL.md §4 step 4 and §5", f"docs/design/specs/{slug}.md"]},
    ]
    out = cards + ladder
    for c in out:
        c["ledger"] = lid(c["id"])
        c.setdefault("context", [])
        c["context"] = list(epic.get("context", [])) + c["context"]
    return out


